cypress_script:
describe('Horizontal Slider Control', () => {
  it('should allow the user to adjust the slider and display the correct value', () => {
    cy.visit('https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('input[type="range"]')
      .invoke('val', 50)
      .trigger('change');
    cy.get('#range').should('have.text', '50');
  });
  it('should not update the displayed value if the slider is not moved', () => {
    cy.visit('https://the-internet.herokuapp.com/horizontal_slider');
    cy.get('#range').should('have.text', '0');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Horizontal Slider Control', () => {
  test('should allow the user to adjust the slider and display the correct value', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/horizontal_slider');
    await page.locator('input[type="range"]').fill('50');
    await page.locator('input[type="range"]').dispatchEvent('change');
    await expect(page.locator('#range')).toHaveText('50');
  });
  test('should not update the displayed value if the slider is not moved', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/horizontal_slider');
    await expect(page.locator('#range')).toHaveText('0');
  });
});
